        <?= view('shared/attachments.php', ['type' => 'credit_note', 'id' => $cid, 'attachments' => $c['attachments'], 'may' => ['attach' => $may['attach'], 'delete' => $may['attach']], 'here' => $here, 'prefix' => 'credit-note']) ?>
