                    <input type="text" inputmode="decimal" name="amount" class="form-control btn-touch mb-2" value="<?= e($c['balance']) ?>" id="credit-note-view-apply-amount" aria-label="Amount"><button type="submit" class="btn btn-primary btn-touch w-100" id="credit-note-view-apply-btn">Apply</button></form><?php endif; ?><?php endif; ?>
