            <?php if ($may['delete']): ?><form method="post" action="/credit-notes/delete.php" hx-post="/credit-notes/delete.php" hx-target="#flash" hx-confirm="Delete this draft?"><?= csrf_field() ?><input type="hidden" name="credit_note" value="<?= $cid ?>"><button type="submit" class="btn btn-light btn-touch w-100 text-danger" id="credit-note-view-delete-btn">Delete the draft</button></form><?php endif; ?>
